<script setup>
import {watch,computed,ref,inject,nextTick} from 'vue'
import {RouterLink} from 'vue-router'
import {cmsApi} from '../../api/cms.api'
import {useBranchStore} from '../../stores/branch'
import {useCmsPage} from '../../composables/useCmsPage'
import {menuProduct} from '../../composables/usePublicMenu'
import {safeContentUrl} from '../../utils/contentUrl'
import CmsSection from '../../components/site/CmsSection.vue'
import ProductCard from '../../components/site/ProductCard.vue'
import SiteOffers from '../../components/site/SiteOffers.vue'
import BranchSelector from '../../components/site/BranchSelector.vue'
import ApiFeedback from '../../components/admin/catalog/ApiFeedback.vue'
const branch=useBranchStore(),page=useCmsPage('home'),bannerIndex=ref(0),query=ref(''),popularElement=ref(null),searchInput=ref(null),{searchOpen,closeSearch}=inject('site')
const products=computed(()=> (page.data.value?.featured_products||[]).map(p=>menuProduct(p,branch.selectedUuid)).filter(p=>!query.value||p.name.includes(query.value)))
function load(){return page.run(signal=>cmsApi.home({branch:branch.selectedUuid||undefined},signal))}
watch(()=>branch.selectedUuid,load);branch.load().then(load);watch(page.data,()=>{bannerIndex.value=0})
watch(searchOpen,async open=>{if(open){await nextTick();(Array.isArray(popularElement.value)?popularElement.value[0]:popularElement.value)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});(Array.isArray(searchInput.value)?searchInput.value[0]:searchInput.value)?.focus()}else query.value=''})
</script>
<template><main id="main"><div v-if="page.loading.value||page.error.value" class="container section-space"><h1 v-if="page.error.value">{{ page.error.value.status===404?'الصفحة الرئيسية غير منشورة':'تعذر تحميل الصفحة الرئيسية' }}</h1><ApiFeedback variant="page" :loading="page.loading.value" :error="page.error.value" @retry="load"/></div><template v-if="page.data.value"><template v-for="section in page.data.value.page.sections" :key="section.id"><section v-if="section.key==='featured_menu'" id="popular" ref="popularElement" class="popular section-space container"><div class="section-heading"><div><span class="section-kicker">{{ section.subtitle }}</span><h2>{{ section.title }}</h2><p>{{ section.content }}</p></div><RouterLink class="text-button" to="/menu">شاهد المنيو الكامل ←</RouterLink></div><div class="search-bar" :hidden="!searchOpen"><label for="home-search">ابحث في الأطباق المميزة</label><input id="home-search" ref="searchInput" v-model="query" type="search"><button class="text-button" @click="closeSearch">إغلاق البحث</button></div><BranchSelector/><div class="products-grid"><ProductCard v-for="product in products" :key="product.id" :product="product"/></div><p v-if="!products.length" class="empty-search">{{ branch.selectedUuid?'لا توجد أطباق مميزة مطابقة.':'اختر فرعًا لعرض أطباقه.' }}</p></section><SiteOffers v-else-if="section.key==='offers'" :offers="page.data.value.active_offers" :title="section.title" :subtitle="section.subtitle"/><section v-else-if="section.key==='gallery_preview'" id="gallery" class="gallery-banner container"><div class="gallery-banner-heading"><div><h2>{{ section.title }}</h2><p>{{ section.subtitle||section.content }}</p></div><RouterLink class="button button-outline" to="/gallery">معرض الصور ←</RouterLink></div><div class="gallery-banner-photos"><figure v-for="item in page.data.value.gallery_preview" :key="item.id" class="gallery-banner-item"><img v-if="safeContentUrl(item.image_url)" class="cms-gallery-photo" :src="safeContentUrl(item.image_url)" :alt="item.alt_text||item.title||''" loading="lazy"><figcaption><h3>{{ item.title }}</h3><p>{{ item.description }}</p></figcaption></figure></div><p v-if="!page.data.value.gallery_preview.length">لا توجد صور منشورة.</p></section><CmsSection v-else :section="section" :page-title="page.data.value.page.title" :banner="section.key==='hero'?page.data.value.banners[bannerIndex]:null"/></template><nav v-if="page.data.value.banners.length>1" class="container module-tabs" aria-label="البانرات الرئيسية"><button v-for="(banner,index) in page.data.value.banners" :key="banner.id" :aria-pressed="bannerIndex===index" @click="bannerIndex=index">{{ banner.title||('البانر '+(index+1)) }}</button></nav><section v-for="banner in page.data.value.secondary_banners" :key="banner.id" class="container section-space"><img v-if="safeContentUrl(banner.image_url)" class="cms-secondary-banner" :src="safeContentUrl(banner.image_url)" :alt="banner.title||''"><h2>{{ banner.title }}</h2><p>{{ banner.subtitle }}</p><a v-if="safeContentUrl(banner.button_url)" class="button button-primary" :href="safeContentUrl(banner.button_url)">{{ banner.button_text }}</a></section></template></main></template>
